package net.civeira.phylax.feature.identity.userfederatedidentity.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class SubjectVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property subject of user federated identity ")
  void test_subject_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> SubjectVO.tryFrom(null));
    Assertions.assertEquals("one", SubjectVO.from("one").getSubject());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> SubjectVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", SubjectVO.from("one").toString());
  }
}
